$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$source=(Get-Content -Raw (Join-Path $root 'modules/scene-bindings/streamerbot/scene-links-engine.cs')).Replace('public class CPHInline {','public class CPHInline { public FakeCPH CPH=new FakeCPH(); public System.Collections.Generic.Dictionary<string,object> args=new System.Collections.Generic.Dictionary<string,object>();')
$fake=@'
using System;using System.Collections.Generic;using System.Linq;using System.Threading;using System.Threading.Tasks;using Newtonsoft.Json.Linq;
public class FakeCPH {
 public class TwitchInfo {public string UserId="fixture",Game="Fixture Category",GameId="fixture-category";}public TwitchInfo TwitchGetBroadcaster(){return new TwitchInfo();}public TwitchInfo TwitchGetExtendedUserInfoById(string id){return new TwitchInfo();}
 public Dictionary<string,object> Globals=new Dictionary<string,object>();public List<string> Effects=new List<string>();public bool Connected=true,FailInventory,FailConfig,FailState,FailCategory,FailFocus,FailWindows;public string Current="Unbound";public int Categories,Focuses,Lists;public Action OnCategory;
 public T GetGlobalVar<T>(string key,bool persisted){return Globals.ContainsKey(key)?(T)Globals[key]:default(T);}
 public void SetGlobalVar(string key,object value,bool persisted){if(FailConfig&&key=="portable.sceneBindings.config"||FailState&&key=="portable.sceneBindings.state")throw new Exception("Synthetic save failure");Globals[key]=value;}
 public bool ObsIsConnected(){return Connected;}public string ObsSendRaw(string type,string data,int connection){if(type!="GetSceneList"||connection!=0||data!="{}")throw new Exception("Unexpected OBS mutation");if(FailInventory)return "{\"requestStatus\":{\"result\":false}}";return new JObject{["currentProgramSceneName"]=Current,["scenes"]=new JArray(new[]{"Unbound","A","B","C","a"}.Select(n=>new JObject{["sceneName"]=n}))}.ToString();}
 public object SetChannelGame(string category){Categories++;Effects.Add("category:"+category);if(OnCategory!=null)OnCategory();return FailCategory?null:new object();}public void WebsocketBroadcastJson(string value){}public void LogError(string value){}public void Wait(int ms){Thread.Sleep(ms);}
}
public class TestEngine:CPHInline { protected override string RunHelper(string mode,string process,string title){if(mode=="List"){CPH.Lists++;if(CPH.FailWindows)throw new Exception("Synthetic timeout");return "[{\"processName\":\"fixture\",\"title\":\"Fixture window\",\"pid\":1}]";}CPH.Focuses++;CPH.Effects.Add("focus:"+process);if(CPH.FailFocus)throw new Exception("Synthetic timeout");return "{\"activated\":true}";} }
public static class Recorder {
 public const string Config="{\"version\":1,\"bindings\":{\"A\":{\"category\":\"Category A\",\"window\":{\"processName\":\"fixture\",\"titleContains\":\"Window\"}},\"B\":{\"category\":\"Category B\",\"window\":{\"processName\":\"fixture\",\"titleContains\":\"Window\"}},\"C\":{\"category\":\"Category C\",\"window\":{\"processName\":\"fixture\",\"titleContains\":\"Window\"}},\"Missing\":{\"category\":\"Retain\",\"window\":{}}}}";
 public static TestEngine Make(FakeCPH shared,string mode,string id=""){var e=new TestEngine();e.CPH=shared;e.args["sceneBindingsMode"]=mode;if(id!="")e.args["requestId"]=id;return e;}
 public static void Event(FakeCPH c,string scene){var e=Make(c,"scene-changed");e.args["obs.sceneName"]=scene;e.Execute();}
 public static void Rapid(){var c=new FakeCPH();c.Globals["portable.sceneBindings.config"]=Config;Make(c,"initialize").Execute();c.Current="A";var a=Task.Run(()=>Event(c,"A"));Thread.Sleep(60);c.Current="B";var b=Task.Run(()=>Event(c,"B"));Thread.Sleep(60);c.Current="C";var last=Task.Run(()=>Event(c,"C"));Task.WaitAll(a,b,last);if(c.Categories!=1||c.Focuses!=1||c.Effects[0]!="category:Category C")throw new Exception("Rapid scene changes did not coalesce");Event(c,"C");if(c.Categories!=1)throw new Exception("Duplicate event repeated side effects");c.Connected=false;Make(c,"initialize").Execute();c.Connected=true;Make(c,"initialize").Execute();Event(c,"C");if(c.Categories!=1)throw new Exception("Reconnect applied current binding");}
 public static void Concurrent(){var c=new FakeCPH();c.Globals["portable.sceneBindings.config"]=Config;Make(c,"initialize").Execute();Parallel.For(0,30,i=>{var e=Make(c,i%2==0?"save":"apply","parallel-"+i);e.args["configJson"]=Config;e.args["sceneName"]="A";e.Execute();});if(c.Categories!=15||c.Focuses!=15||((JObject)JObject.Parse((string)c.Globals["portable.sceneBindings.config"])["bindings"]).Count!=4)throw new Exception("Concurrent Save/Apply lost state or repeated effects");}
 public static void Superseded(){var c=new FakeCPH();c.Globals["portable.sceneBindings.config"]=Config;Make(c,"initialize").Execute();Task next=null;c.OnCategory=()=>{c.OnCategory=null;c.Current="C";next=Task.Run(()=>Event(c,"C"));Thread.Sleep(80);};c.Current="A";Event(c,"A");next.Wait();if(c.Categories!=2||c.Focuses!=1||c.Effects.Last()!="focus:fixture")throw new Exception("Superseded category continued with stale focus");}
}
'@
$refs=@((Get-ChildItem -LiteralPath (Join-Path $PSHOME 'ref') -Filter '*.dll').FullName)+(Join-Path $PSHOME 'Newtonsoft.Json.dll')
Add-Type -TypeDefinition ('namespace SceneLinksTest{'+$fake+'}namespace SceneLinksTest{'+$source+'}') -ReferencedAssemblies $refs -CompilerOptions '/nowarn:1701,1702'
function Assert($ok,$message){if(-not $ok){throw $message}}
function Run($e,[hashtable]$arguments){$e.args.Clear();foreach($v in $arguments.GetEnumerator()){$e.args[$v.Key]=$v.Value};[void]$e.Execute()}
function Payload($e){return ($e.CPH.Globals['portable.sceneBindings.state']|ConvertFrom-Json).payload}
$e=[SceneLinksTest.TestEngine]::new();Run $e @{sceneBindingsMode='initialize'};Assert (@((Payload $e).config.bindings.PSObject.Properties).Count -eq 0) 'Fresh installations must be empty';Assert ($e.CPH.Categories -eq 0 -and $e.CPH.Focuses -eq 0) 'Startup must be inert'
$e.CPH.Globals['portable.sceneBindings.config']=[SceneLinksTest.Recorder]::Config;Run $e @{sceneBindingsMode='initialize'};Run $e @{sceneBindingsMode='refresh';requestId='refresh'};Assert ((Payload $e).lastRequestId -eq 'refresh' -and $e.CPH.Categories -eq 0) 'Refresh must acknowledge without effects';Assert ((Payload $e).missingScenes -contains 'Missing') 'Missing mappings must remain'
Run $e @{sceneBindingsMode='save';configJson='{}';requestId='save'};Assert ($e.CPH.Categories -eq 0 -and $e.CPH.Focuses -eq 0) 'Save must not execute';$saved=$e.CPH.Globals['portable.sceneBindings.config'];Run $e @{sceneBindingsMode='save';configJson='{broken';requestId='bad'};Assert ($saved -eq $e.CPH.Globals['portable.sceneBindings.config'] -and (Payload $e).operation.status -eq 'error') 'Malformed JSON must not destroy saved mappings';Run $e @{sceneBindingsMode='save';configJson='{"bindings":{"A":{"window":17}}}'};Assert ($saved -eq $e.CPH.Globals['portable.sceneBindings.config']) 'Malformed windows must be rejected'
Run $e @{sceneBindingsMode='apply';sceneName='a';requestId='case'};Assert ($e.CPH.Categories -eq 0) 'Scene names must match exactly';Run $e @{sceneBindingsMode='apply';sceneName='A';requestId='apply'};Assert ($e.CPH.Categories -eq 1 -and $e.CPH.Focuses -eq 1 -and (Payload $e).operation.status -eq 'ok') 'Apply must execute both saved effects';Run $e @{sceneBindingsMode='apply';sceneName='A';requestId='apply'};Assert ($e.CPH.Categories -eq 1) 'Same completed request must not repeat'
Run $e @{sceneBindingsMode='test-focus';windowJson='{"processName":"fixture","titleContains":"draft"}';requestId='focus'};Assert ($e.CPH.Categories -eq 1 -and $e.CPH.Focuses -eq 2) 'Test Focus must not update category';Run $e @{sceneBindingsMode='test-category';category='Draft';requestId='category'};Assert ($e.CPH.Categories -eq 2 -and $e.CPH.Focuses -eq 2) 'Test Category must not focus'
$e.CPH.FailCategory=$true;Run $e @{sceneBindingsMode='apply';sceneName='A';requestId='partial'};Assert ((Payload $e).operation.status -eq 'partial' -and (Payload $e).lastExecution.focus.status -eq 'success') 'Category failure must not prevent focus';$e.CPH.FailCategory=$false;$e.CPH.FailFocus=$true;Run $e @{sceneBindingsMode='test-focus';windowJson='{"processName":"fixture"}'};Assert ((Payload $e).operation.status -eq 'partial') 'Helper timeout must not report success';$e.CPH.FailFocus=$false
$e.CPH.FailInventory=$true;Run $e @{sceneBindingsMode='refresh'};Assert (-not (Payload $e).obsAvailable) 'Rejected inventory must report unavailable';$e.CPH.FailInventory=$false;$e.CPH.Connected=$false;$count=$e.CPH.Categories;Run $e @{sceneBindingsMode='apply';sceneName='A'};Assert ($e.CPH.Categories -eq $count -and (Payload $e).operation.status -eq 'error') 'Disconnected OBS must prevent Apply';$e.CPH.Connected=$true
$e.CPH.FailConfig=$true;Run $e @{sceneBindingsMode='save';configJson='{"bindings":{}}'};Assert ($saved -eq $e.CPH.Globals['portable.sceneBindings.config']) 'Failed persistence must retain map';$e.CPH.FailConfig=$false;$e.CPH.FailState=$true;$count=$e.CPH.Categories;Run $e @{sceneBindingsMode='apply';sceneName='A'};Assert ($e.CPH.Categories -eq $count) 'Failed running-state persistence must prevent effects';$e.CPH.FailState=$false
[SceneLinksTest.Recorder]::Rapid();[SceneLinksTest.Recorder]::Concurrent();[SceneLinksTest.Recorder]::Superseded()
$native=[SceneLinksTest.CPHInline]::new();Run $native @{sceneBindingsMode='initialize'};Assert ((Payload $native).windowsError -eq '') 'The real embedded helper must list windows successfully';Run $native @{sceneBindingsMode='test-focus';windowJson='{"processName":"companion_fixture_absent_7e9c","titleContains":"Unicode Ω; $notCode"}'};Assert ((Payload $native).operation.status -eq 'partial') 'The real encoded helper must reject an absent target without activating another window'
Write-Output 'Actual Scene Links C# passed: empty/preserved maps, read-only startup/save/refresh/reconnect, exact names, independent tests, validation/persistence failures, partial results, debounce/duplicate/superseded events and concurrent Save/Apply. Synthetic OBS/Twitch/focus only.'
